={{ (() => {
  const raw = typeof $json.body?.country === 'string' ? $json.body.country.trim().toLowerCase() : 'india';
  const map = { india: 'in', 'united states': 'us', usa: 'us', uk: 'gb', canada: 'ca', australia: 'au' };
  const code = map[raw] || raw;
  return /^[a-z]{2}$/.test(code) ? code : 'in';
})() }}

