conditions.leftValue:
={{ (() => {
  try {
    const u = new URL($json.Website || '');
    const h = u.hostname.toLowerCase();
    const isIPv4 = /^\d{1,3}(?:\.\d{1,3}){3}$/.test(h);
    const isIPv6 = h.includes(':');
    const blockedHost = h === 'localhost' || h.endsWith('.localhost') || h.endsWith('.local') || h.endsWith('.internal') || h.endsWith('.test') || h.endsWith('.invalid');
    return u.protocol === 'https:' && !u.username && !u.password && !u.port && !isIPv4 && !isIPv6 && !blockedHost && h.includes('.') && !h.startsWith('.') && !h.endsWith('.');
  } catch {
    return false;
  }
})() }}
